import{gunzipSync}from'node:zlib';import{mkdtempSync,mkdirSync,writeFileSync}from'node:fs';import{tmpdir}from'node:os';import{resolve,dirname,sep,join}from'node:path';import{spawn}from'node:child_process';
const test=process.argv.includes('--test'),demo=process.argv.includes('--demo');if(!test&&!demo)throw Error('Use --test or --demo. For persistent local work, unzip the current source.');
const root=mkdtempSync(join(tmpdir(),'oweleaf-'));const tree=JSON.parse(gunzipSync(Buffer.from('','base64')).toString());for(const[name,data]of Object.entries(tree)){const p=resolve(root,name);if(!p.startsWith(root+sep))throw Error('Unsafe source path');mkdirSync(dirname(p),{recursive:true});writeFileSync(p,Buffer.from(data,'base64'));}
console.log('Oweleaf isolated '+(test?'test':'fixture demo')+' workspace: '+root);const p=spawn(process.execPath,test?['--test','test/*.test.js']:['src/server.js'],{cwd:root,stdio:'inherit',env:{...process.env,FARTHING_MOCK:'1',BRAIN_PROVIDER:'heuristic'}});p.on('exit',code=>process.exitCode=code??1);
